// spec: .qa/e2e/specs/admin-content.md 1.2 · seed: tests/seed.admin.spec.ts · тикет #686cecdc (AC 15, 16)
// Только просмотр → @prod-safe. Загрузку ловим детерминированно: запрос данных вкладки (RSC GET /content?…&_rsc=)
// удерживается, пока проверяется каркас, затем отпускается. Без пауз.
import { test, expect } from '@playwright/test';
import { adminAs, closeAdmin, contentQueue, openContent } from '../moderation-menu/mod-helpers';

test.describe('מסך ניהול תוכן — состояния', () => {
  test('Смена вкладки — каркас «טוען את הרשימה» (aria-busy) до ответа; поиск без совпадений — «לא נמצא תוכן תואם» @desktop @prod-safe (#686cecdc)', async ({ browser }) => {
    test.setTimeout(90_000);
    const page = await adminAs(browser);
    try {
      await openContent(page);
      await expect(page.getByRole('tab', { name: /^לבדיקה/ })).toHaveAttribute('aria-selected', 'true');

      // Загрузка (AC 16): держим ответ RSC для вкладки «כל התוכן»
      let release!: () => void;
      const held = new Promise<void>((r) => (release = r));
      let caught = false;
      await page.route(
        (u) => u.pathname === '/content' && u.searchParams.has('_rsc') && u.searchParams.get('tab') === 'all',
        async (route) => {
          caught = true;
          await held;
          await route.continue().catch(() => undefined);
        },
      );
      await page.getByRole('tab', { name: 'כל התוכן' }).click();
      await expect(page.getByRole('tab', { name: 'כל התוכן' })).toHaveAttribute('aria-selected', 'true');
      const loading = contentQueue(page).getByRole('status', { name: 'טוען את הרשימה' });
      await expect(loading).toBeVisible();
      await expect(contentQueue(page).locator('[aria-busy="true"]').first()).toBeVisible();
      expect(caught, 'запрос данных вкладки удержан').toBe(true);
      release();
      await expect(loading).toHaveCount(0);
      await expect(contentQueue(page).getByRole('list').first().getByRole('link').first()).toBeVisible();
      await page.unrouteAll({ behavior: 'ignoreErrors' });

      // Пусто (AC 15): поиск без совпадений
      const q = 'QA-AUTO-nothing-' + Date.now();
      await page.getByRole('textbox', { name: 'חיפוש בתוכן' }).fill(q);
      await page.getByRole('textbox', { name: 'חיפוש בתוכן' }).press('Enter');
      await expect(page).toHaveURL(new RegExp(`q=${q}`));
      await expect(contentQueue(page).getByText('לא נמצא תוכן תואם')).toBeVisible();
      await expect(contentQueue(page).getByRole('list').first().getByRole('link')).toHaveCount(0);
    } finally {
      await closeAdmin(page);
    }
  });
});
